/** Station spacing in metres. Wide enough that neighbouring traces don't read as one. */
export const STATION_SPACING = 5;

/** World position for station `i`, laid out as a straight line on Z = 0. */
export function motifPosition(index: number, count: number): { x: number; z: number } {
  const span = (count - 1) * STATION_SPACING;
  return { x: index * STATION_SPACING - span / 2, z: 0 };
}
